               // transition the button press logic will execute.\n\n#define PIXEL_PIN    3    // Digital IO pin connected to the NeoPixels.\n\n#define PIXEL_COUNT 60\n\n// Parameter 1 = number of pixels in strip,  neopixel stick has 8\n// Parameter 2 = pin number (most are valid)\n// Parameter 3 = pixel type flags, add together as needed:\n//   NEO_RGB     Pixels are wired for RGB bitstream\n//   NEO_GRB     Pixels are wired for GRB bitstream, correct for neopixel stick\n//   NEO_KHZ400  400 KHz bitstream (e.g. FLORA pixels)\n//   NEO_KHZ800  800 KHz bitstream (e.g. High Density LED strip), correct for neopixel stick\nAdafruit_NeoPixel strip = Adafruit_NeoPixel(PIXEL_COUNT, PIXEL_PIN, NEO_GRB + NEO_KHZ800);\n\nbool oldState = LOW;\nuint8_t color_pos = 0;\nint i=0;\nint longpress=2000;\nlong timecheck;\n\nvoid setup() {\n  pinMode(BUTTON_PIN, INPUT_PULLUP);\n  strip.begin();\n  strip.clear();\n  strip.show(); // Initialize all pixels to 'off'\n  Serial.begin(9600); \n}\n\nvoid loop()\n{\n\n  // Get current button state.\n  bool newState = digitalRead(BUTTON_PIN);\n\n  // Check if state changed from low to high (button press).\n  if (newState == HIGH && oldState == LOW) {\n      timecheck = millis(); \n    // Short delay to debounce button.\n    delay(20);\n    // Check if button is still low after debounce.\n    newState = digitalRead(BUTTON_PIN);\n    if (newState == HIGH){\n      color_pos+=8;\n      strip.setPixelColor(0, Wheel(color_pos));\n      strip.show();\n    }\n  }\n\n if( millis()-timecheck > 300)\n {\n   if (digitalRead(BUTTON_PIN)==HIGH)\n   {\n if(millis()-timecheck > longpress)\n {\n  while(digitalRead(BUTTON_PIN) == HIGH)\n  {\n  strip.setPixelColor(0,Wheel(color_pos));\n  strip.show();\n  delay(300);\n\n  strip.setPixelColor(0,0,0,0);\n  strip.show();\n  delay(300);\n  bool newState = digitalRead(BUTTON_PIN);\n  }\n  strip.setPixelColor(0,0,0,0);\n  strip.show();\n   timecheck = millis(); \n }\n  }\n   }\n\n  // Set the last button state to the old state.\n  oldState = newState;\n}\n\n// Input a value 0 to 255 to get a color value.\n// The colours are a transition r - g - b - back to r.\nuint32_t Wheel(byte WheelPos) {\n  WheelPos = 255 - WheelPos;\n  if(WheelPos < 85) {\n    return strip.Color(255 - WheelPos * 3, 0, WheelPos * 3);\n  }\n  if(WheelPos < 170) {\n    WheelPos -= 85;\n    return strip.Color(0, WheelPos * 3, 255 - WheelPos * 3);\n  }\n  WheelPos -= 170;\n  return strip.Color(WheelPos * 3, 255 - WheelPos * 3, 0);\n}\n\n"})}),"\n",(0,t.jsxs)(n.ul,{children:["\n",(0,t.jsxs)(n.li,{children:["\n",(0,t.jsxs)(n.p,{children:[(0,t.jsx)(n.strong,{children:"\u6B65\u9AA4 4."})," \u4E0A\u4F20\u793A\u4F8B\u7A0B\u5E8F\u3002\u5982\u679C\u4F60\u4E0D\u77E5\u9053\u5982\u4F55\u4E0A\u4F20\u4EE3\u7801\uFF0C\u8BF7\u67E5\u770B ",(0,t.jsx)(n.a,{href:"https://wiki.seeedstudio.com/cn/Upload_Code/",children:"\u5982\u4F55\u4E0A\u4F20\u4EE3\u7801"}),"\u3002"]}),"\n"]}),"\n",(0,t.jsxs)(n.li,{children:["\n",(0,t.jsxs)(n.p,{children:[(0,t.jsx)(n.strong,{children:"\u6B65\u9AA4 5."})," \u6BCF\u6B21\u6309\u4E0B Grove-Mech Keycap\uFF0C\u4F60\u90FD\u4F1A\u770B\u5230 LED \u989C\u8272\u53D1\u751F\u53D8\u5316\u3002\u5982\u679C\u6309\u4F4F\u6309\u94AE\u5927\u7EA6 2 \u79D2\uFF0C\u4F60\u4F1A\u770B\u5230\u547C\u5438\u706F\u6548\u679C\u3002"]}),"\n"]}),"\n"]}),"\n",(0,t.jsx)(n.h3,{id:"\u4F7F\u7528-raspberry-pi-\u73A9\u8F6C",children:"\u4F7F\u7528 Raspberry Pi \u73A9\u8F6C"}),"\n",(0,t.jsx)(n.h4,{id:"\u786C\u4EF6-2",children:"\u786C\u4EF6"}),"\n",(0,t.jsxs)(n.ul,{children:["\n",(0,t.jsxs)(n.li,{children:[(0,t.jsx)(n.strong,{children:"\u6B65\u9AA4 1"}),". \u672C\u9879\u76EE\u4E2D\u4F7F\u7528\u7684\u7269\u54C1\uFF1A"]}),"\n"]}),"\n",(0,t.jsxs)(n.table,{children:[(0,t.jsx)(n.thead,{children:(0,t.jsxs)(n.tr,{children:[(0,t.jsx)(n.th,{children:"Raspberry pi"}),(0,t.jsx)(n.th,{children:"Grove Base Hat for RasPi"}),(0,t.jsx)(n.th,{children:"Grove - Mech Keycap"})]})}),(0,t.jsxs)(n.tbody,{children:[(0,t.jsxs)(n.tr,{children:[(0,t.jsx)(n.td,{children: